//! Cross-check PDF source identity with Poppler against a six-page repeated
//! image fixture generated by the original Python OCR regression suite.

#![cfg(feature = "pdf-integration")]

use std::{collections::BTreeSet, fs, process::Command};

use pdf_redox_ocr::{
    PageNumber,
    native_images::{NativeImageBudget, native_source_images},
    paint_scan::enumerate_image_paints,
    pdf_metadata::PdfMetadata,
};

#[test]
fn one_native_image_decodes_once_across_six_paints() -> Result<(), Box<dyn std::error::Error>> {
    let pdfimages = Command::new("pdfimages").arg("-v").output()?;
    if !pdfimages.status.success() {
        return Err("Poppler pdfimages is required for native source tests".into());
    }
    let temp = tempfile::tempdir()?;
    let pdf = temp.path().join("repeated-image.pdf");
    fs::write(
        &pdf,
        include_bytes!("fixtures/repeated-image-six-pages.pdf"),
    )?;
    let metadata = PdfMetadata::open(&pdf)?;
    assert_eq!(metadata.page_count(), 6);
    let pages = (1..=6)
        .map(PageNumber::new)
        .collect::<Result<Vec<_>, _>>()?;
    let painted = enumerate_image_paints(&metadata, &pages)?;
    assert_eq!(painted.placements.len(), 6);
    let source_ids = painted
        .placements
        .iter()
        .map(|paint| paint.source_id.clone())
        .collect::<BTreeSet<_>>();
    assert_eq!(source_ids, BTreeSet::from(["9:0".to_owned()]));

    let images = native_source_images(
        &pdf,
        &pages,
        &source_ids,
        NativeImageBudget {
            source_pixels: 500_000,
            ..NativeImageBudget::default()
        },
    )?;
    assert_eq!(images.len(), 1);
    let image = images.get("9:0").ok_or("source 9:0 not decoded")?;
    assert_eq!((image.width(), image.height()), (1200, 300));
    assert!(image.pixels().any(|pixel| pixel.0 != [255, 255, 255]));
    // Valid PDFs must fall back when the native memory or extraction ceiling
    // cannot pay for the entire source.
    let over_budget = native_source_images(
        &pdf,
        &pages,
        &source_ids,
        NativeImageBudget {
            source_pixels: 500_000,
            total_pixels: 100_000,
            ..NativeImageBudget::default()
        },
    )?;
    assert!(over_budget.is_empty());
    let over_extraction_limit = native_source_images(
        &pdf,
        &pages,
        &source_ids,
        NativeImageBudget {
            extraction_pixels: 100_000,
            ..NativeImageBudget::default()
        },
    )?;
    assert!(over_extraction_limit.is_empty());
    Ok(())
}

#[test]
fn inline_images_consume_extraction_ceiling_without_becoming_sources()
-> Result<(), Box<dyn std::error::Error>> {
    let pdf_bytes = include_bytes!("fixtures/inline-plus-source-budget.pdf");
    let temp = tempfile::tempdir()?;
    let pdf = temp.path().join("inline-plus-image.pdf");
    fs::write(&pdf, pdf_bytes)?;
    let page = PageNumber::new(1)?;
    let painted = enumerate_image_paints(&PdfMetadata::open(&pdf)?, &[page])?;
    assert_eq!(painted.placements.len(), 1, "{painted:#?}");
    let wanted = BTreeSet::from([painted.placements[0].source_id.clone()]);
    let too_small = native_source_images(
        &pdf,
        &[page],
        &wanted,
        NativeImageBudget {
            extraction_pixels: 519_999,
            ..NativeImageBudget::default()
        },
    )?;
    assert!(too_small.is_empty());
    let fits = native_source_images(
        &pdf,
        &[page],
        &wanted,
        NativeImageBudget {
            extraction_pixels: 520_000,
            ..NativeImageBudget::default()
        },
    )?;
    assert_eq!(fits.len(), 1);
    let source = fits
        .get(&painted.placements[0].source_id)
        .ok_or("native source missing after inline extraction")?;
    assert_eq!((source.width(), source.height()), (1200, 300));
    Ok(())
}
